    void IGeneratedComponent.ResetToDefault()
    {
        Owner.SetSilent(default!);
        SourceLife.SetSilent(default!);
        SourceLifeGeneration.SetSilent(0UL);
        FuseEndTick.SetSilent(0UL);
        Power.SetSilent(0);
        ChainId.SetSilent(0UL);
        BombKind.SetSilent(0);
        PierceLayers.SetSilent(0);
        SkillLevel.SetSilent(0);
        Phase.SetSilent(0);
        ExplodedAtTick.SetSilent(0UL);
        DangerUntilTick.SetSilent(0UL);
        BurnUntilTick.SetSilent(0UL);
        ReachUp.SetSilent(0);
        ReachDown.SetSilent(0);
        ReachLeft.SetSilent(0);
        ReachRight.SetSilent(0);
        KickDirection.SetSilent(0);
        KickRange.SetSilent(0);
        KickStartTick.SetSilent(0UL);
        CapacityReturned.SetSilent(false);
        PlacedAtTick.SetSilent(0UL);
        PlacementRecorded.SetSilent(false);
        HitFamily.SetSilent(default!);
        FutureChildren.SetSilent(0);
        SplitSubmittedMask.SetSilent(0);
        SplitResolvedMask.SetSilent(0);
        ChildDirection.SetSilent(0);
        PromiseToken.SetSilent(string.Empty);
        Frenzy.SetSilent(false);
        TraversalOriginX.SetSilent(0);
        TraversalOriginZ.SetSilent(0);
        TraversalPower.SetSilent(0);
        ((ISyncContainer)TerrainContinuations).ResetForReuse();
        ((ISyncContainer)HitParticipants).ResetForReuse();
        ((ISyncContainer)HitLives).ResetForReuse();
        ((ISyncContainer)HitLifeGenerations).ResetForReuse();
        ((ISyncContainer)HitStates).ResetForReuse();
        ((ISyncContainer)ContactedChests).ResetForReuse();
        ((ISyncContainer)HitHandleWorlds).ResetForReuse();
        ((ISyncContainer)HitHandleInstances).ResetForReuse();
        ((ISyncContainer)HitHandleGenerations).ResetForReuse();
        ((ISyncContainer)HitDependentsAdmitted).ResetForReuse();
        ((ISyncContainer)TraversalArms).ResetForReuse();
    }
